function branchRows(options){return options.map((o,i)=>`<div class="branch-draft-row"><div class="field"><label>选项文字</label><input name="label" value="${esc(o.text||'')}" required maxlength="200"></div><div class="field"><label>进入的分支章节</label><select name="destination"><option value="__new__">＋ 新建分支章节</option>${sceneOptions(o.target)}</select></div><div class="field"><label>新章节名称（新建时填写）</label><input name="chapterName" maxlength="80" placeholder="例如：神社线 · 初次约定"></div><button class="btn small" type="button" data-action="branch-remove-row">删除选项</button></div>`).join('')}
function openBranchEditor(id=''){const existing=scene().blocks.find(b=>b.id===id&&b.type==='choice');dialog(existing?'编辑选项分支':'设计选项分支',`<p>玩家选择选项后进入对应章节。可连接已有章节，或新建独立分支。新章节创建后需要添加剧情。</p><div class="field"><label>选择提示</label><input name="prompt" required value="${esc(existing?.text||'你想如何选择？')}"></div><div id="branchDraft">${branchRows(existing?.options||[{text:'前往神社'},{text:'留在山下'}])}</div><button class="btn small" type="button" data-action="branch-add-row">＋ 添加选项</button>`,'保存分支',f=>{try{const rows=[...$('#branchDraft').children].map(row=>({text:row.querySelector('[name="label"]').value.trim(),target:row.querySelector('[name="destination"]').value,name:row.querySelector('[name="chapterName"]').value.trim()}));if(rows.length<2)throw Error('至少保留两个选项');if(rows.some(r=>!r.text||r.target==='__new__'&&!r.name))throw Error('请填写选项文字和新章节名称');const names=rows.filter(r=>r.target==='__new__').map(r=>r.name);if(new Set(names).size!==names.length||names.some(name=>project.scenes.some(s=>s.name===name)))throw Error('新章节名称不能重复，请选择已有章节或换一个名称');change(()=>{const options=rows.map(r=>{if(r.target==='__new__'){const s={id:uid(),name:r.name,blocks:[]};project.scenes.push(s);return {text:r.text,target:s.id}}return {text:r.text,target:r.target}});if(existing){existing.text=f.get('prompt').trim();existing.options=options;selected=existing.id}else{const b={id:uid(),type:'choice',text:f.get('prompt').trim(),options},i=scene().blocks.findIndex(b=>b.id===selected);scene().blocks.splice(i<0?scene().blocks.length:i+1,0,b);selected=b.id}stopContentPlayback();view='script';mode='visual'});notify('分支已保存，可前往目标章节编写剧情')}catch(e){notify(e.message)}});$('#modal').classList.add('wide');if(!existing)$('#branchDraft').querySelectorAll('[name="destination"]').forEach(el=>el.value='__new__')}
const branchEffectDraw=draw,branchEffectInspector=drawInspector,branchEffectOther=otherView,branchEffectFields=visualEffectFields,branchEffectValidate=validateProject;
draw=function(){branchEffectDraw();if(view==='script'){$('.tool-strip')?.insertAdjacentHTML('beforeend','<button class="btn primary small" data-action="design-branch" title="设计选项并连接目标章节">设计分支</button><button class="btn small" data-action="import-effect">导入特效</button>')}};
drawInspector=function(){branchEffectInspector();const b=block();if(b?.type==='choice'){$('#inspector').insertAdjacentHTML('afterbegin',`<button class="btn primary" data-action="edit-branch" data-id="${esc(b.id)}">设计分支 / 新建分支章节</button><p class="field-note">每个选项独立指定章节；章节结尾可插入跳转块汇入共同章节。</p>`);$('#inspector').querySelectorAll('[data-option][data-prop="text"]').forEach(input=>input.closest('.field-row').insertAdjacentHTML('beforeend',`<button class="btn small" data-action="branch-delete-option" data-id="${input.dataset.option}">删除选项</button>`))}if(b?.type==='effect')$('#inspector').insertAdjacentHTML('beforeend','<div class="card-actions"><button class="btn small" data-action="import-effect">导入图片 / 动图 / 预设</button><button class="btn small" data-action="export-effect">导出特效预设</button></div>')};
otherView=function(){if(view!=='flow')return branchEffectOther();return `<div class="full-content"><p class="field-note">每个选项连接独立章节。点击目标章节进入编辑，使用跳转剧情块可让分支重新汇合。</p><button class="btn primary" data-action="design-branch">＋ 设计选项分支</button><div class="route-board">${project.scenes.map(s=>`<section class="settings-card"><h3><button data-action="scene" data-id="${esc(s.id)}">${esc(s.name)}</button></h3>${s.blocks.filter(b=>['choice','jump'].includes(b.type)).map(b=>b.type==='choice'?`<div class="route-choice"><strong>${esc(b.text)}</strong>${sourceBlockButton(s,b)}<button class="btn small" data-action="flow-edit-branch" data-scene="${esc(s.id)}" data-id="${esc(b.id)}">编辑分支</button>${b.options.map(o=>`<p>${esc(o.text)} → <button class="btn small" data-action="scene" data-id="${esc(o.target||s.id)}">${esc(project.scenes.find(t=>t.id===o.target)?.name||(o.target?'目标已不存在':'结束故事'))}</button></p>`).join('')}</div>`:`<p>跳转 → ${esc(project.scenes.find(t=>t.id===b.target)?.name||'结束故事')} ${sourceBlockButton(s,b)}</p>`).join('')||'<p class="field-note">尚未设置分支或跳转，章末结束故事。</p>'}</section>`).join('')}</div></div>`};
visualEffectFields=function(value={},editing=false){const attrs=k=>editing?`data-vfx="${k}"`:`name="${k}"`;return branchEffectFields(value,editing)+`<section class="external-effect-fields"><h3>外部叠加特效</h3><div class="field"><label>图片 / GIF / 动态 WebP（类型选“导入叠加特效”时使用）</label><select ${attrs('asset')}>${assetOptions(value.asset)}</select></div><div class="field-row"><div class="field"><label>适配</label><select ${attrs('fit')}>${optionList({cover:'铺满画面',contain:'完整显示'},value.fit||'cover')}</select></div><div class="field"><label>混合模式</label><select ${attrs('blend')}>${optionList({normal:'正常',screen:'滤色（适合黑底光效）',add:'发光叠加',multiply:'正片叠底'},value.blend||'normal')}</select></div></div><button type="button" class="btn small" data-action="import-effect">导入本地特效 / 预设</button><p class="field-note">支持 PNG、JPEG、GIF、WebP 和 Kotoba JSON 特效预设。透明图片可覆盖舞台；特效播放结束后恢复画面。</p></section>`};
function applyExternalEffect(values,media,projectId){if(project.id!==projectId){notify('工程已切换，未写入本次特效');return}const form=$('#modal.open #dialogForm')||($('#modal').open?$('#dialogForm'):null),editingForm=form?.elements.namedItem('effect');change(()=>{if(media){media.id=uid();media.folderId=libraryDestinationFolder();project.assets.push(media);values.asset=media.id}if(!editingForm){if(block()?.type==='effect')Object.assign(block(),values);else{const b={id:uid(),type:'effect',...values,text:KotobaCore.visualEffects[values.effect]},i=scene().blocks.findIndex(b=>b.id===selected);scene().blocks.splice(i<0?scene().blocks.length:i+1,0,b);selected=b.id;view='script';mode='visual'}}});if(editingForm){const select=form.elements.namedItem('asset');if(select)select.innerHTML=assetOptions(values.asset);for(const [key,v]of Object.entries(values))if(form.elements.namedItem(key))form.elements.namedItem(key).value=v}notify('特效已导入')}
async function importExternalEffect(){const projectId=project.id;pickFile('.png,.jpg,.jpeg,.gif,.webp,.json',async file=>{notify('正在读取特效素材…');try{let values,media;if(file.name.toLowerCase().endsWith('.json')){if(file.size>32*1024*1024)throw Error('预设文件超过 32 MB');const parsed=JSON.parse(await file.text());if(parsed.format!=='kotoba-effect'||parsed.version!==1||!Object.hasOwn(KotobaCore.visualEffects,parsed.settings?.effect))throw Error('请选择 Kotoba 特效预设 JSON');values=KotobaCore.effectSettings(parsed.settings);if(parsed.media){if(typeof parsed.media.data!=='string'||!/^data:image\/(png|jpeg|gif|webp);base64,[A-Za-z0-9+/]*={0,2}$/.test(parsed.media.data))throw Error('预设中的特效图片格式不受支持');const data=parsed.media.data.split(',')[1];if(data.length*3/4-(data.endsWith('==')?2:data.endsWith('=')?1:0)>MAX_ASSET_BYTES)throw Error('预设图片超过 20 MB');media={name:String(parsed.media.name||'导入特效'),type:'image',data:parsed.media.data}}else if(values.effect==='overlay')throw Error('叠加预设需要包含图片素材')}else{if(file.size>MAX_ASSET_BYTES)throw Error('请选择不超过 20 MB 的特效素材');if(!/^image\/(png|jpeg|gif|webp)$/.test(file.type))throw Error('请选择 PNG、JPEG、GIF 或 WebP');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('素材读取失败'));reader.readAsDataURL(file)});media={name:file.name,type:'image',data};values={...KotobaCore.effectSettings({effect:'overlay',duration:1500,intensity:100}),fit:'contain',blend:'normal'}}if(projectStorageEstimate()+(media?.data.length||0)>256*1024*1024-65536)throw Error('导入后工程将超过 256 MB');await prepareEditorMedia(media);applyExternalEffect(values,media,projectId)}catch(e){notify('导入失败：'+e.message)}})}
async function exportExternalEffect(){const b=block();if(b?.type!=='effect')return;const settings=KotobaCore.effectSettings(b),media=asset(settings.asset),preset={format:'kotoba-effect',version:1,settings,...(media?{media:{name:media.name,data:media.data}}:{})};delete settings.asset;await download((KotobaCore.visualEffects[b.effect]||'特效')+'.json',JSON.stringify(preset,null,2),'application/json',{kind:'json'})}
validateProject = function (p) {
  branchEffectValidate(p);
  const destinations = new Set(p.scenes.map(s => s.id));
  for (const s of p.scenes) {
    for (const [index, b] of s.blocks.entries()) {
      if (b.type === 'choice') {
        const invalid = b.options.find(o => !o.text.trim() || (o.target && !destinations.has(o.target)));
        if (!b.options.length || invalid) {
          const label = invalid?.text?.trim();
          const problem = !b.options.length ? '至少需要一个选项' : label ? `选项「${label}」的目标章节不存在` : '选项文字不能为空';
          const error = Error(`「${s.name}」第 ${index + 1} 个剧情块：${problem}`);
          error.sceneId = s.id;
          error.blockId = b.id;
          throw error;
        }
      }
      if (b.type === 'effect' && b.effect === 'overlay' && !p.assets.some(a => a.id === b.asset && a.type === 'image')) {
        const error = Error(`「${s.name}」第 ${index + 1} 个剧情块：叠加特效尚未绑定图片`);
        error.sceneId = s.id;
        error.blockId = b.id;
        throw error;
      }
    }
  }
  return p;
};
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]'),a=button?.dataset.action;if(!['design-branch','edit-branch','flow-edit-branch','branch-add-row','branch-remove-row','branch-delete-option','import-effect','export-effect'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();if(a==='design-branch')openBranchEditor();if(a==='edit-branch')openBranchEditor(button.dataset.id);if(a==='flow-edit-branch'){sceneId=button.dataset.scene;selected=button.dataset.id;openBranchEditor(selected)}if(a==='branch-add-row'){$('#branchDraft').insertAdjacentHTML('beforeend',branchRows([{text:''}]));$('#branchDraft').lastElementChild.querySelector('[name="destination"]').value='__new__'}if(a==='branch-remove-row'){if($('#branchDraft').children.length<=2)notify('至少保留两个选项');else button.closest('.branch-draft-row').remove()}if(a==='branch-delete-option'){if(block()?.options.length<=2)notify('至少保留两个选项');else change(()=>block().options.splice(Number(button.dataset.id),1))}if(a==='import-effect')importExternalEffect();if(a==='export-effect')exportExternalEffect().catch(error=>notify('导出预设失败：'+error.message))},true);
draw();
